import os
import re
import pandas as pd
from PIL import Image
import pytesseract
from datetime import datetime

IMG_DIR = '/app/workspace/dataset/img'
OUTPUT_FILE = '/app/workspace/stat_ocr.xlsx'

def extract_date(text):
    # Regex patterns
    # We look for:
    # YYYY-MM-DD
    # DD-MM-YYYY
    # DD/MM/YYYY
    # DD.MM.YYYY
    # DD MMM YYYY (27 JAN 2026)

    patterns = [
        r'\b(\d{4}-\d{2}-\d{2})\b',
        r'\b(\d{2}-\d{2}-\d{4})\b',
        r'\b(\d{2}/\d{2}/\d{4})\b',
        r'\b(\d{2}\.\d{2}\.\d{4})\b',
        r'\b(\d{1,2}\s+(?:JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*\s+\d{4})\b'
    ]

    lines = text.split('\n')
    for line in lines:
        for pat in patterns:
            match = re.search(pat, line, re.IGNORECASE)
            if match:
                date_str = match.group(1)
                # Cleanup
                date_str = date_str.strip()

                try:
                    # YYYY-MM-DD
                    if re.match(r'^\d{4}-\d{2}-\d{2}$', date_str):
                        return date_str

                    # DD-MM-YYYY
                    if re.match(r'^\d{2}-\d{2}-\d{4}$', date_str):
                        return datetime.strptime(date_str, "%d-%m-%Y").strftime("%Y-%m-%d")

                    # DD/MM/YYYY
                    if re.match(r'^\d{2}/\d{2}/\d{4}$', date_str):
                        return datetime.strptime(date_str, "%d/%m/%Y").strftime("%Y-%m-%d")

                    # DD.MM.YYYY
                    if re.match(r'^\d{2}\.\d{2}\.\d{4}$', date_str):
                        return datetime.strptime(date_str, "%d.%m.%Y").strftime("%Y-%m-%d")

                    # DD MMM YYYY
                    # Remove extra spaces
                    date_str_clean = ' '.join(date_str.split())
                    # Parse
                    # Try short month first
                    try:
                        return datetime.strptime(date_str_clean, "%d %b %Y").strftime("%Y-%m-%d")
                    except ValueError:
                        try:
                            return datetime.strptime(date_str_clean, "%d %B %Y").strftime("%Y-%m-%d")
                        except ValueError:
                            pass

                except ValueError:
                    continue
    return None

def extract_amount(text):
    lines = text.split('\n')
    # Filter empty
    lines = [l.strip() for l in lines if l.strip()]

    exclusion_keywords = [
        "SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED"
    ]

    # Priority groups
    priorities = [
        ["GRAND TOTAL"],
        ["TOTAL RM", "TOTAL: RM"],
        ["TOTAL AMOUNT"],
        ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL"]
    ]

    def find_price(s):
        # Remove commas
        s_clean = s.replace(',', '')
        # Regex for number with exactly 2 decimal places
        # \d+\.\d{2}
        matches = re.findall(r'\b(\d+\.\d{2})\b', s_clean)
        if matches:
            return matches[-1] # Return the last one found
        return None

    for priority_group in priorities:
        for idx, line in enumerate(lines):
            line_upper = line.upper()

            # Check exclusion
            if any(exc in line_upper for exc in exclusion_keywords):
                continue

            # Check keyword
            # Using exact word match for keywords might be safer but substrings is requested by prompt "containing these keywords"
            match_keyword = False
            for kw in priority_group:
                if kw in line_upper:
                    match_keyword = True
                    break

            if match_keyword:
                # Search for price in this line
                price = find_price(line)
                if price:
                    return price

                # Check next line
                if idx + 1 < len(lines):
                    next_line = lines[idx+1]
                    price_next = find_price(next_line)
                    if price_next:
                        return price_next

    return None

def main():
    if not os.path.exists(IMG_DIR):
        print(f"Directory {IMG_DIR} does not exist.")
        return

    files = sorted([f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png'))])

    results = []

    print(f"Found {len(files)} images.")

    for f in files:
        path = os.path.join(IMG_DIR, f)
        try:
            # Load image
            img = Image.open(path)
            # OCR
            text = pytesseract.image_to_string(img)

            date_val = extract_date(text)
            amount_val = extract_amount(text)

            # Handle nulls
            # Pandas handles None as null/empty in Excel

            results.append({
                "filename": f,
                "date": date_val,
                "total_amount": amount_val
            })
            # print(f"{f}: {date_val}, {amount_val}")

        except Exception as e:
            print(f"Error processing {f}: {e}")
            results.append({
                "filename": f,
                "date": None,
                "total_amount": None
            })

    df = pd.DataFrame(results)
    df = df[['filename', 'date', 'total_amount']]

    try:
        df.to_excel(OUTPUT_FILE, index=False, sheet_name='results')
        print(f"Successfully wrote to {OUTPUT_FILE}")
    except Exception as e:
        print(f"Failed to write excel: {e}")

if __name__ == "__main__":
    main()

