import os
import re
import pandas as pd
from PIL import Image
import pytesseract
from datetime import datetime

IMG_DIR = '/app/workspace/dataset/img'
OUTPUT_FILE = '/app/workspace/stat_ocr.xlsx'

# Tesseract configuration
# PSM 6: Assume a single uniform block of text. Good for receipts.
TESS_CONFIG = '--psm 6'

def extract_date(text):
    # Regex patterns
    patterns = [
        r'(\d{4}-\d{2}-\d{2})',
        r'(\d{2}-\d{2}-\d{4})',
        r'(\d{2}/\d{2}/\d{4})',
        r'(\d{2}\.\d{2}\.\d{4})',
        r'(\d{1,2}\s+(?:JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*\s+\d{4})',
        r'(\d{2}/\d{2}/\d{2})',
        r'(\d{2}-\d{2}-\d{2})'
    ]

    lines = text.split('\n')
    for line in lines:
        for pat in patterns:
            match = re.search(pat, line, re.IGNORECASE)
            if match:
                date_str = match.group(1)
                date_str = date_str.strip()

                # Correction for invalid months (e.g. 19/62/2018 -> 19/02/2018)
                # Check for DD/MM/YYYY or DD-MM-YYYY
                if re.match(r'^\d{2}[/-]\d{2}[/-]\d{4}$', date_str):
                    parts = re.split(r'[/-]', date_str)
                    d, m, y = parts[0], parts[1], parts[2]
                    if int(m) > 12:
                        # Common OCR error: 6 -> 0
                        if m.startswith('6'):
                            m = '0' + m[1:]
                            date_str = f"{d}/{m}/{y}" # Normalize to / for parsing

                try:
                    # YYYY-MM-DD
                    if re.match(r'^\d{4}-\d{2}-\d{2}$', date_str):
                        return date_str

                    # DD-MM-YYYY
                    if re.match(r'^\d{2}-\d{2}-\d{4}$', date_str):
                        return datetime.strptime(date_str, "%d-%m-%Y").strftime("%Y-%m-%d")

                    # DD/MM/YYYY
                    if re.match(r'^\d{2}/\d{2}/\d{4}$', date_str):
                        return datetime.strptime(date_str, "%d/%m/%Y").strftime("%Y-%m-%d")

                    # DD.MM.YYYY
                    if re.match(r'^\d{2}\.\d{2}\.\d{4}$', date_str):
                        return datetime.strptime(date_str, "%d.%m.%Y").strftime("%Y-%m-%d")

                    # DD MMM YYYY
                    if re.search(r'[A-Z]', date_str, re.IGNORECASE):
                        date_str_clean = ' '.join(date_str.split())
                        try:
                            return datetime.strptime(date_str_clean, "%d %b %Y").strftime("%Y-%m-%d")
                        except:
                            try:
                                return datetime.strptime(date_str_clean, "%d %B %Y").strftime("%Y-%m-%d")
                            except:
                                pass

                    # DD/MM/YY
                    if re.match(r'^\d{2}/\d{2}/\d{2}$', date_str):
                        return datetime.strptime(date_str, "%d/%m/%y").strftime("%Y-%m-%d")

                    # DD-MM-YY
                    if re.match(r'^\d{2}-\d{2}-\d{2}$', date_str):
                        return datetime.strptime(date_str, "%d-%m-%y").strftime("%Y-%m-%d")

                except ValueError:
                    continue
    return None

def extract_amount(text):
    lines = text.split('\n')
    lines = [l.strip() for l in lines if l.strip()]

    # Revised exclusion keywords
    # Removed "GST", "TAX" to allow "Total including GST"
    exclusion_keywords = [
        "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL", "SUB TUTAL", "SUB-TUTAL",
        "DISCOUNT", "CHANGE", "CASH TENDERED",
        "GST TOTAL", "TAX TOTAL", "GST SUMMARY", "TAX SUMMARY",
        "GST AMOUNT", "TAX AMOUNT", "TOTAL TAX", "TOTAL GST"
    ]

    # Priority groups
    priorities = [
        ["GRAND TOTAL"],
        ["TOTAL RM", "TOTAL: RM"],
        ["TOTAL AMOUNT"],
        ["TOTAL SALES", "TOTAL INCL", "TOTAL AFTER ADJ", "NETT TOTAL", "NET TOTAL", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE"],
        ["TOTAL"], # Generic total
        ["PAYMENT", "VISA", "MASTERCARD", "CASH"] # Fallback if Total is missed
    ]

    def clean_ocr_number(s):
        s = s.replace('O', '0').replace('o', '0').replace('u', '0').replace('U', '0')
        s = s.replace('l', '1').replace('I', '1').replace('i', '1')
        s = s.replace('S', '5').replace('s', '5')
        s = s.replace('Z', '2').replace('z', '2')
        # Common error 7 -> 1 is dangerous to automate globally, but maybe context specific?
        return s

    def find_price(s, loose=False):
        s_clean = s.replace(',', '')

        # Strict search
        matches = re.findall(r'(\d+\.\d{2})', s_clean)
        if matches:
            return matches[-1]

        if loose:
            dirty_matches = re.findall(r'(\d+\.[0-9uUoOiIlSsZz]{2})', s_clean)
            if dirty_matches:
                candidate = dirty_matches[-1]
                cleaned = clean_ocr_number(candidate)
                try:
                    float(cleaned)
                    return cleaned
                except:
                    pass
        return None

    for priority_group in priorities:
        for idx, line in enumerate(lines):
            line_upper = line.upper()

            # Check exclusion
            if any(exc in line_upper for exc in exclusion_keywords):
                continue

            # Check keyword
            match_keyword = False
            for kw in priority_group:
                if kw in line_upper:
                    match_keyword = True
                    break

            if match_keyword:
                price = find_price(line, loose=True)
                if price:
                    return price

                if idx + 1 < len(lines):
                    next_line = lines[idx+1]
                    price_next = find_price(next_line, loose=True)
                    if price_next:
                        return price_next

    return None

def main():
    if not os.path.exists(IMG_DIR):
        print(f"Directory {IMG_DIR} does not exist.")
        return

    files = sorted([f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png'))])

    results = []

    print(f"Found {len(files)} images.")

    for f in files:
        path = os.path.join(IMG_DIR, f)
        try:
            img = Image.open(path)
            # Use PSM 6
            text = pytesseract.image_to_string(img, config=TESS_CONFIG)

            date_val = extract_date(text)
            amount_val = extract_amount(text)

            results.append({
                "filename": f,
                "date": date_val,
                "total_amount": amount_val
            })

        except Exception as e:
            print(f"Error processing {f}: {e}")
            results.append({
                "filename": f,
                "date": None,
                "total_amount": None
            })

    df = pd.DataFrame(results)

    def format_amount(x):
        if x is None:
            return None
        try:
            f = float(x)
            return f"{f:.2f}"
        except:
            return str(x)

    df['total_amount'] = df['total_amount'].apply(format_amount)

    df = df[['filename', 'date', 'total_amount']]

    try:
        df.to_excel(OUTPUT_FILE, index=False, sheet_name='results')
        print(f"Successfully wrote to {OUTPUT_FILE}")
    except Exception as e:
        print(f"Failed to write excel: {e}")

if __name__ == "__main__":
    main()

